import { edit_delete_categories_for_product } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    categoryinfo: Object,
    categorydelete: Boolean
  },
  data() {
    return {
      loading: false
    };
  },
  watch: {
    categorydelete: {
      async handler() {
        if (this.categorydelete == true) {
          //  console.log( this.$store.getters.GetUserObj.user.user_email_id);
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      this.loading = true;
      // var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(edit_delete_categories_for_product, {
          input: {
            categorie_name: this.categoryinfo.categorie_name,
            categorie_id: this.categoryinfo.categorie_id
          }
        }));
        var response = JSON.parse(result.data.edit_delete_categories_for_product);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          // this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
